@Component
public class TopicLocalCache {
    private static final String CHANNEL = "cache:invalidate";
    private static final Duration TTL = Duration.ofMinutes(10);

    private final Cache<String, String> local = Caffeine.newBuilder()
            .maximumSize(20_000)
            .expireAfterWrite(Duration.ofSeconds(30))
            .build();
    private final StringRedisTemplate redis;
    private final TopicRepository repository;

    public TopicLocalCache(StringRedisTemplate redis, TopicRepository repository) {
        this.redis = redis;
        this.repository = repository;
    }

    public String read(String slug) {
        String key = "topic:detail:" + slug;
        String hit = local.getIfPresent(key);
        if (hit != null) {
            return hit;
        }
        String value = redis.opsForValue().get(key);
        if (value == null) {
            value = repository.findPublishedJson(slug).orElse("{}");
            redis.opsForValue().set(key, value, TTL);
        }
        local.put(key, value);
        return value;
    }

    // 写路径调用：本机失效 -> 删 Redis -> 广播给其他实例
    public void evict(String slug) {
        String key = "topic:detail:" + slug;
        local.invalidate(key);
        redis.delete(key);
        redis.convertAndSend(CHANNEL, key);
    }

    public void onMessage(byte[] body) {
        local.invalidate(new String(body, StandardCharsets.UTF_8));
    }
}
